def book_reservations_in_order(user_id: str, reservations: list):
    """
    Book TWO OR MORE reservations for one user, one after the other, in EXACTLY the order of the list.
    Use this instead of calling book_reservation several times (parallel book_reservation calls run in a
    random order). Typical case: the user splits the passengers into separate reservations so that each
    reservation can use its own certificate.

    Order: put the reservations in the order the user listed them. If the user mentioned themselves first
    ("me with the $500 certificate, then Raj, then Liam"), the account holder's reservation is FIRST.

    Each reservation is checked with the same rules as book_reservation (payment ids from the profile, at most
    one certificate / one credit card / three gift cards per reservation, balances, amounts add up to the price,
    flights form the trip, profile dates of birth, free bag allowance). ALL reservations are checked before
    the first one is booked; if one is invalid, NOTHING is booked and the error says which one.

    Example (round trip, 3 legs, $871 per passenger, two reservations):
        book_reservations_in_order(user_id="<user id>", reservations=[
            {"origin": "AAA", "destination": "BBB", "flight_type": "round_trip", "cabin": "business",
             "flights": [{"flight_number": "<outbound from search>", "date": "2024-05-26"},
                         {"flight_number": "<return leg 1>", "date": "2024-05-28"}, {"flight_number": "<return leg 2>", "date": "2024-05-28"}],
             "passengers": [{"first_name": "<holder first>", "last_name": "<holder last>", "dob": "<holder dob from profile>"}],
             "payment_methods": [{"payment_id": "<certificate id>", "amount": 500}, {"payment_id": "<credit card id>", "amount": 371}],
             "total_baggages": 0, "nonfree_baggages": 0, "insurance": "no"},
            {"origin": "AAA", "destination": "BBB", "flight_type": "round_trip", "cabin": "business",
             "flights": [<same flights>],
             "passengers": [{"first_name": "<second passenger first>", "last_name": "<last>", "dob": "<dob>"}],
             "payment_methods": [{"payment_id": "<another certificate id>", "amount": 250}, {"payment_id": "<credit card id>", "amount": 621}],
             "total_baggages": 0, "nonfree_baggages": 0, "insurance": "no"}])

    Args:
        user_id: The ID of the user who books all the reservations, such as 'sara_doe_496'.
        reservations: List of reservations, in booking order. Each item is a dict with EXACTLY the book_reservation fields: "origin" (IATA code), "destination" (IATA code; for a round_trip the airport the outbound goes to), "flight_type" ("one_way" or "round_trip"), "cabin" ("basic_economy", "economy" or "business"), "flights" (list of {"flight_number", "date"}), "passengers" (list of {"first_name", "last_name", "dob"}), "payment_methods" (list of {"payment_id", "amount"}), "total_baggages" (int), "nonfree_baggages" (int), "insurance" ("yes" or "no").

    Returns:
        {"result": "SUCCESS ...", "reservations": [one booked reservation per item, in order]} or an "Error: ..." string.
    """
    def _book_one(user_id, origin, destination, flight_type, cabin, flights, passengers, payment_methods, total_baggages, nonfree_baggages, insurance, _dry=False):
        def _d(x):
            if hasattr(x, "model_dump"):
                return x.model_dump()
            return dict(x)

        flights = [_d(f) for f in flights]
        passengers = [_d(p) for p in passengers]
        payment_methods = [_d(p) for p in payment_methods]
        notes = []

        user = env_get_user_details(user_id=user_id)
        if not isinstance(user, dict):
            return user
        methods = user.get("payment_methods") or {}

        def _describe(m):
            s = m.get("id", "") + " (" + str(m.get("source"))
            if m.get("brand"):
                s += ", " + str(m.get("brand"))
            if m.get("last_four"):
                s += " ending in " + str(m.get("last_four"))
            if m.get("amount") is not None:
                s += ", balance $" + str(m.get("amount"))
            return s + ")"

        available = "; ".join(_describe(m) for m in methods.values())

        # 1. payment ids must exist in the profile
        for p in payment_methods:
            pid = p.get("payment_id")
            if pid not in methods:
                return ("Error: payment_id '" + str(pid) + "' is not in this user's profile. "
                        "Use one of these exact ids: " + available + ". "
                        "If you are not sure which one the user means, ask the user.")

        # 2. per-type limits from the policy
        counts = {"certificate": 0, "credit_card": 0, "gift_card": 0}
        for p in payment_methods:
            src = methods[p["payment_id"]].get("source")
            if src in counts:
                counts[src] += 1
        if counts["certificate"] > 1:
            return ("Error: a reservation can use at most ONE travel certificate, but " + str(counts["certificate"]) +
                    " were given. Nothing was booked. Tell the user only one certificate can be used per reservation "
                    "and ask which ONE certificate to use and how to pay the rest (credit card / gift cards). "
                    "If the user wants, the passengers can instead be booked as separate reservations, each with its own certificate: "
                    "then call book_reservations_in_order ONCE with all of them, in the order the user listed them.")
        if counts["credit_card"] > 1:
            return "Error: a reservation can use at most ONE credit card. Nothing was booked. Ask the user which one credit card to use."
        if counts["gift_card"] > 3:
            return "Error: a reservation can use at most THREE gift cards. Nothing was booked. Ask the user which gift cards to use."

        # 3. balances
        for p in payment_methods:
            m = methods[p["payment_id"]]
            if m.get("source") in ("certificate", "gift_card") and m.get("amount") is not None:
                if float(p.get("amount", 0)) > float(m["amount"]):
                    return ("Error: " + p["payment_id"] + " has a balance of $" + str(m["amount"]) +
                            " but $" + str(p.get("amount")) + " was requested from it. Nothing was booked. "
                            "Use at most the balance and pay the rest with another allowed method.")

        # 4. account holder / saved passengers: use the date of birth stored in the profile
        known = {}
        nm = user.get("name") or {}
        if user.get("dob") and nm.get("first_name") and nm.get("last_name"):
            known[(nm["first_name"].strip().lower(), nm["last_name"].strip().lower())] = user["dob"]
        for sp in user.get("saved_passengers") or []:
            if sp.get("first_name") and sp.get("last_name") and sp.get("dob"):
                known.setdefault((sp["first_name"].strip().lower(), sp["last_name"].strip().lower()), sp["dob"])
        for p in passengers:
            key = «redacted» "")).strip().lower(), str(p.get("last_name", "")).strip().lower())
            if key in known and p.get("dob") != known[key]:
                notes.append("dob of " + p.get("first_name", "") + " " + p.get("last_name", "") +
                             " set to " + known[key] + " from the user profile (was " + str(p.get("dob")) + ")")
                p["dob"] = known[key]

        # 5. connecting legs: use the leg dates returned by the one-stop search
        for i in range(len(flights) - 1):
            a, b = flights[i], flights[i + 1]
            for o, dst in ((origin, destination), (destination, origin)):
                res = env_search_onestop_flight(origin=o, destination=dst, date=a.get("date"))
                if not isinstance(res, list):
                    continue
                hit = None
                for pair in res:
                    if (isinstance(pair, list) and len(pair) == 2
                            and pair[0].get("flight_number") == a.get("flight_number")
                            and pair[1].get("flight_number") == b.get("flight_number")):
                        hit = pair
                        break
                if hit is not None:
                    d2 = hit[1].get("date")
                    if d2 and d2 != b.get("date"):
                        notes.append("date of connecting flight " + b["flight_number"] + " corrected from " +
                                     str(b.get("date")) + " to " + d2 + " (the date of that leg in the one-stop search)")
                        b["date"] = d2
                    break

        # 6. the flights must form the trip (checked only when every leg's route is known)
        cache = {}

        def _search(kind, a, b, date):
            key = «redacted» a, b, date)
            if key not in cache:
                if kind == "direct":
                    cache[key] = env_search_direct_flight(origin=a, destination=b, date=date)
                else:
                    cache[key] = env_search_onestop_flight(origin=a, destination=b, date=date)
            return cache[key] if isinstance(cache[key], list) else []

        def _prev(date):
            try:
                import datetime as _dt
                return (_dt.date.fromisoformat(date) - _dt.timedelta(days=1)).isoformat()
            except Exception:
                return None

        def _find(fn, date):
            for (a, b) in ((origin, destination), (destination, origin)):
                for x in _search("direct", a, b, date):
                    if x.get("flight_number") == fn:
                        return (x.get("origin"), x.get("destination"))
                for dd in (date, _prev(date)):
                    if not dd:
                        continue
                    for pair in _search("onestop", a, b, dd):
                        for x in pair:
                            if x.get("flight_number") == fn and x.get("date") in (None, date):
                                return (x.get("origin"), x.get("destination"))
            return None

        if flight_type == "round_trip" and origin == destination:
            return ("Error: for a round_trip, destination must be the airport the outbound journey goes TO (where the "
                    "return journey starts), not the origin again. Nothing was booked. Example: JFK -> SFO and back is "
                    "origin='JFK', destination='SFO'. Call again with the correct destination.")

        legs = [_find(f.get("flight_number"), f.get("date")) for f in flights]
        if flights and all(legs):
            desc = ", ".join(f.get("flight_number", "") + " " + l[0] + "->" + l[1] + " " + str(f.get("date"))
                             for f, l in zip(flights, legs))
            problem = None
            if legs[0][0] != origin:
                problem = "the first flight must depart from " + origin
            for i in range(len(legs) - 1):
                if problem is None and legs[i][1] != legs[i + 1][0]:
                    problem = ("flight " + flights[i]["flight_number"] + " arrives at " + legs[i][1] + " but the next flight " +
                               flights[i + 1]["flight_number"] + " departs from " + legs[i + 1][0] + " (a leg is missing)")
            if problem is None and flight_type == "one_way" and legs[-1][1] != destination:
                problem = "a one_way trip must end at " + destination
            if problem is None and flight_type == "round_trip" and (legs[-1][1] != origin or destination not in [l[1] for l in legs]):
                problem = "a round_trip must go to " + destination + " and end back at " + origin
            if problem:
                return ("Error: the flights do not form the trip: " + problem + ". Nothing was booked. Flights given: " + desc +
                        ". Include every leg (both legs of a one-stop connection), outbound first, then return, "
                        "copied from search_direct_flight / search_onestop_flight / search_itineraries_by_price.")

        # 7. free bag allowance depends on the booking user's membership and the cabin (policy table);
        #    if more bags were marked non-free than the allowance requires, fix it and take the overcharge
        #    off the payments (credit card first, then gift cards, then certificate)
        _free = {"regular": {"basic_economy": 0, "economy": 1, "business": 2},
                 "silver": {"basic_economy": 1, "economy": 2, "business": 3},
                 "gold": {"basic_economy": 2, "economy": 3, "business": 4}}
        try:
            allowance = _free.get(str(user.get("membership")), _free["regular"]).get(cabin, 0) * len(passengers)
            tb, nb = int(total_baggages), int(nonfree_baggages)
        except Exception:
            allowance, tb, nb = None, None, None
        if allowance is not None and nb > max(0, tb - allowance):
            new_nb = max(0, tb - allowance)

            def _price(fn, date):
                for (a, b) in ((origin, destination), (destination, origin)):
                    for x in _search("direct", a, b, date):
                        if x.get("flight_number") == fn:
                            return (x.get("prices") or {}).get(cabin)
                    for dd in (date, _prev(date)):
                        if not dd:
                            continue
                        for pair in _search("onestop", a, b, dd):
                            for x in pair:
                                if x.get("flight_number") == fn and x.get("date") in (None, date):
                                    return (x.get("prices") or {}).get(cabin)
                return None

            prices = [_price(f.get("flight_number"), f.get("date")) for f in flights]
            paid = sum(float(p.get("amount", 0)) for p in payment_methods)
            if flights and all(x is not None for x in prices):
                base = sum(prices) * len(passengers) + (30 * len(passengers) if insurance == "yes" else 0)
                excess = 50 * (nb - new_nb)
                if abs(paid - (base + 50 * nb)) < 0.01:
                    order = sorted(payment_methods, key=«redacted» p: {"credit_card": 0, "gift_card": 1}.get(
                        methods[p["payment_id"]].get("source"), 2))
                    left = excess
                    for p in order:
                        take = min(left, float(p.get("amount", 0)))
                        if take <= 0:
                            continue
                        p["amount"] = p["amount"] - take
                        if float(p["amount"]).is_integer():
                            p["amount"] = int(p["amount"])
                        left -= take
                    payment_methods = [p for p in payment_methods if float(p.get("amount", 0)) > 0]
                notes.append("nonfree_baggages corrected from " + str(nb) + " to " + str(new_nb) + ": a " +
                             str(user.get("membership")) + " member gets " + str(allowance) + " free checked bag(s) in " +
                             str(cabin) + " for " + str(len(passengers)) + " passenger(s), so " + str(tb) +
                             " bag(s) cost $" + str(50 * new_nb) + ". Final payment split: " +
                             ", ".join(p["payment_id"] + " $" + str(p["amount"]) for p in payment_methods) +
                             ". Tell the user these exact amounts.")
                nonfree_baggages = new_nb

        # 8. certificate remainder is lost: use the certificate up to its balance before other methods
        cert = None
        for p in payment_methods:
            if methods[p["payment_id"]].get("source") == "certificate":
                cert = p
        if cert is not None:
            room = float(methods[cert["payment_id"]].get("amount") or 0) - float(cert.get("amount", 0))
            if room > 0:
                others = [p for p in payment_methods if p is not cert and float(p.get("amount", 0)) > 0]
                others.sort(key=«redacted» p: 0 if methods[p["payment_id"]].get("source") == "credit_card" else 1)
                moved = 0
                for p in others:
                    take = min(room - moved, float(p.get("amount", 0)))
                    if take <= 0:
                        break
                    p["amount"] = p["amount"] - take
                    if float(p["amount"]).is_integer():
                        p["amount"] = int(p["amount"])
                    moved += take
                if moved > 0:
                    cert["amount"] = cert["amount"] + moved
                    if float(cert["amount"]).is_integer():
                        cert["amount"] = int(cert["amount"])
                    payment_methods = [p for p in payment_methods if p is cert or float(p.get("amount", 0)) > 0]
                    notes.append("moved $" + str(int(moved) if float(moved).is_integer() else moved) + " onto certificate " +
                                 cert["payment_id"] + " (unused certificate balance would be lost). Final payment split: " +
                                 ", ".join(p["payment_id"] + " $" + str(p["amount"]) for p in payment_methods) +
                                 ". Tell the user these exact amounts.")

        if _dry:
            return {"ok": True, "payment_methods": payment_methods, "nonfree_baggages": nonfree_baggages, "notes": notes}
        result = env_book_reservation(user_id=user_id, origin=origin, destination=destination, flight_type=flight_type, cabin=cabin, flights=flights, passengers=passengers, payment_methods=payment_methods, total_baggages=total_baggages, nonfree_baggages=nonfree_baggages, insurance=insurance)
        if isinstance(result, dict) and notes:
            result["notes"] = notes
        return result

    _fields = ["origin", "destination", "flight_type", "cabin", "flights", "passengers", "payment_methods",
               "total_baggages", "nonfree_baggages", "insurance"]
    items = []
    for i, r in enumerate(reservations or []):
        if hasattr(r, "model_dump"):
            r = r.model_dump()
        if not isinstance(r, dict):
            return "Error: reservation #" + str(i + 1) + " is not an object with the book_reservation fields. Nothing was booked."
        missing = [k for k in _fields if k not in r]
        if missing:
            return ("Error: reservation #" + str(i + 1) + " is missing " + ", ".join(missing) +
                    ". Nothing was booked. Each item needs: " + ", ".join(_fields) + ".")
        items.append({k: r[k] for k in _fields})
    if not items:
        return "Error: reservations is empty. Nothing was booked."

    # check every reservation first (nothing is booked if any is invalid)
    planned = []
    for i, r in enumerate(items):
        chk = _book_one(user_id=user_id, _dry=True, **r)
        if not (isinstance(chk, dict) and chk.get("ok")):
            return "Error in reservation #" + str(i + 1) + " (nothing was booked): " + str(chk)
        planned.append(chk)

    # balances are shared across the reservations: a certificate / gift card can not be spent twice
    user = env_get_user_details(user_id=user_id)
    methods = (user.get("payment_methods") or {}) if isinstance(user, dict) else {}
    used = {}
    for chk in planned:
        for p in chk["payment_methods"]:
            used[p["payment_id"]] = used.get(p["payment_id"], 0) + float(p.get("amount", 0))
    for pid, amt in used.items():
        m = methods.get(pid) or {}
        if m.get("source") in ("certificate", "gift_card") and m.get("amount") is not None and amt > float(m["amount"]) + 0.001:
            return ("Error: " + pid + " has a balance of $" + str(m["amount"]) + " but the reservations together use $" +
                    str(amt) + " from it. Nothing was booked. Use each certificate in only one reservation and keep each "
                    "gift card's total within its balance.")

    booked = []
    for i, r in enumerate(items):
        out = _book_one(user_id=user_id, **r)
        if not isinstance(out, dict):
            return {"result": "Error: reservation #" + str(i + 1) + " failed: " + str(out) +
                              ". Reservations #1-#" + str(i) + " WERE booked (listed below); the rest were not.",
                    "booked": booked}
        booked.append(out)
    return {"result": "SUCCESS: booked " + str(len(booked)) + " reservations in this order: " +
                      ", ".join(str(b.get("reservation_id")) for b in booked) + ". Tell the user each reservation id and its payment split.",
            "reservations": booked}
